    correction: [{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">7 + |x| - 5 = 1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">7 - 5 = 2</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">2 + |x| = 1</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 1 - 2</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">1 - 2 = -1</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-1 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
