    correction: [{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">-(x - y + 5) = -x + y - 5</span>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [-x + y - 5 + x - 7] = -y + 5 + 7</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [5 + y - x + 1] = -5 - y + x - 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -3 - y + 5 + 7 - 5 - y + x - 1 + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = x + (-y - y) + (-3 + 5 + 7 - 5 - 1 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-3 + 5 + 7 - 5 - 1 + 1 = 4</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - 2y + 4</span>"}],
