    enonce: "ليكن a و b عددين صحيحين نسبيين؛ قارن X و Y حيث <span dir=\"ltr\" class=\"expr\">X = (11 + a) - b</span>  و  <span dir=\"ltr\" class=\"expr\">Y = (a - 7) - b</span>",
    correction: [{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">X - Y = (11 + a - b) - (a - 7 - b)</span>"},{"quoi":"تختفي المجاهيل","math":"<span dir=\"ltr\" class=\"expr\">X - Y = 11 + 7</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">X - Y = 18</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">18 &gt; 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">X &gt; Y</span>"}],
